// ===============================================================
// WF4 - Lawyer Review & Approval
// Node: "Build Review Email"  (Code -> Run Once for All Items)
//
// Composes the notification a reviewer receives, and pre-builds the
// parameter array for the Postgres INSERT that follows.
//
// Why a Code node instead of writing the body inline in the SQL
// node: the body is multi-line text stitched from two upstream
// nodes plus a runtime URL. Expressed as one n8n expression it
// would be unreadable and untestable. Here it is plain JS, lives in
// git, and the next node just consumes $json.params.
// ===============================================================

// Bug #1: a Postgres node REPLACES its input. "Create Review
// Request" returned only the four RETURNING columns, so the clause
// details are gone from $json. Reach back to the node that had them.
const clause = $('Fetch Clause').first().json;
const request = $('Create Review Request').first().json;

// The form URL is generated by n8n at run time and is unique to
// THIS execution. Reading it here - before the flow reaches the
// Wait node - is what lets the email carry a working link.
const formUrl = $execution.resumeFormUrl;

// ---------------------------------------------------------------
// Recipient resolved outside the code, never hardcoded. A different
// deployment reviews with a different lawyer and only edits the
// config node (or sets the Variable, on an instance that has them).
//
// $env is deliberately NOT used: n8n Cloud blocks environment
// access at the platform level and it cannot be re-enabled without
// a docker-compose file. Resolution order:
//   1. n8n Variable REVIEW_EMAIL  (Settings -> Variables, Enterprise)
//   2. review_email from "Config - Review Settings"
//
// Fail loudly on a blank address. A silently missing recipient
// would create a review request that no human is ever told about,
// and the execution would sit waiting forever.
// ---------------------------------------------------------------
const varsEmail =
  typeof $vars !== 'undefined' && $vars ? $vars.REVIEW_EMAIL : null;
const configEmail = $('Config - Review Settings').first().json.review_email;

const toAddress = String(varsEmail || configEmail || '').trim();
if (!toAddress) {
  throw new Error(
    'REVIEW_EMAIL not resolved. Set review_email on the ' +
      '"Config - Review Settings" node.'
  );
}

// Human-readable explanation of WHY this clause was routed. The
// routing rule is evidence-based, so the email states the evidence
// rather than a bare number - a lawyer can act on "we could not
// find this text in the contract"; they cannot act on "0.75".
const attribution = clause.attribution || 'unknown';
let reason;

if (attribution === 'not_found') {
  reason =
    'The model returned this clause text, but it could NOT be located ' +
    'anywhere in the source document. It is most likely a paraphrase ' +
    'rather than a verbatim quote. Please check the contract and either ' +
    'approve it, correct it with the true wording, or reject it.';
} else if (clause.is_absent === true) {
  reason =
    'The model reported that this clause type is ABSENT from the ' +
    'contract, and the risk of that being wrong is high ' +
    '(risk score ' + clause.risk_score + '). Please confirm the clause ' +
    'is genuinely missing.';
} else {
  reason = 'This clause was flagged for manual review.';
}

const subject =
  '[Clause Review] ' + clause.clause_type + ' - ' + clause.filename;

// Plain text, not HTML. The outbox row is read by a human during the
// demo and later by a Gmail node; plain text renders correctly in both.
const bodyText = [
  'A clause extraction needs your review.',
  '',
  'Document      : ' + clause.filename,
  'Clause type   : ' + clause.clause_type,
  'Risk level    : ' + clause.risk_level + ' (score ' + clause.risk_score + ')',
  'Model conf.   : ' + clause.confidence,
  'Attribution   : ' + attribution,
  '',
  'Why you are seeing this:',
  reason,
  '',
  '--- Extracted clause text ---',
  clause.clause_text || '(the model reported this clause as absent)',
  '--- end ---',
  '',
  'Record your decision here:',
  formUrl,
  '',
  'On the form:',
  '  approve  - the extraction is correct as-is',
  '  correct  - paste the true clause wording into "Corrected clause text"',
  '  reject   - this is not a valid instance of this clause type',
  '',
  'Review request #' + request.review_request_id +
  ' (token ' + request.token + ')',
].join('\n');

// Bug #2: the Query Parameters field splits a plain string on
// commas, which would shred any clause text containing a comma.
// Building the array here and passing it bare as {{ $json.params }}
// sidesteps the splitter entirely.
return [
  {
    json: {
      review_request_id: request.review_request_id,
      token: request.token,
      clause_id: request.clause_id,
      document_id: request.document_id,
      form_url: formUrl,
      params: [
        'clause_review',                      // $1 purpose
        Number(request.review_request_id),    // $2 review_request_id
        Number(request.document_id),          // $3 document_id
        toAddress,                            // $4 to_address
        subject,                              // $5 subject
        bodyText,                             // $6 body_text
      ],
    },
  },
];

// ===============================================================
// WF4 - Lawyer Review & Approval
// Node: "Normalise Decision"  (Code -> Run Once for All Items)
//
// Runs immediately after the execution resumes from the review
// form. Three jobs:
//
//   1. Reattach context. The Wait node emits ONLY the submitted
//      form fields - clause_id, review_request_id and the rest are
//      gone from $json, same failure mode as bug #1 with Postgres
//      nodes. We reach back to the nodes that still hold them.
//
//   2. Rename fields. Form labels contain spaces ("Corrected clause
//      text"), which are clumsy in Switch conditions and in SQL
//      parameter arrays. Everything becomes snake_case here, once.
//
//   3. Validate. A 'correct' decision with no replacement text
//      violates a CHECK constraint in migration 004. Catching it
//      here produces a readable error instead of a raw Postgres
//      constraint violation three nodes later.
// ===============================================================

const form = $input.first().json;

// Context carried forward from before the wait. These nodes ran in
// the same execution, so their data survived the pause-and-resume.
const email = $('Build Review Email').first().json;
const clause = $('Fetch Clause').first().json;

// Form labels -> snake_case. Bracket syntax is required because the
// label literally contains spaces.
const decision = (form['Decision'] || '').trim().toLowerCase();
const correctedTextRaw = form['Corrected clause text'] || '';
const reviewerNoteRaw = form['Review note'] || '';

const correctedText = correctedTextRaw.trim();
const reviewerNote = reviewerNoteRaw.trim();

// ---------------------------------------------------------------
// Validation
// ---------------------------------------------------------------

// Defence in depth. The dropdown only offers three values, but a
// form POST can be crafted by hand, and a typo in the node config
// would otherwise route silently into the Switch's fallback.
const allowed = ['approve', 'correct', 'reject'];
if (!allowed.includes(decision)) {
  throw new Error(
    'Invalid decision "' + decision + '". Expected one of: ' +
    allowed.join(', ')
  );
}

// Migration 004 enforces this at the database level. Enforcing it
// here too means the reviewer gets a meaningful message rather than
// a constraint violation, and no half-finished update is attempted.
if (decision === 'correct' && correctedText.length === 0) {
  throw new Error(
    'Decision "correct" requires text in the "Corrected clause text" ' +
    'field. Nothing was submitted, so there is no wording to record.'
  );
}

// A correction that matches the original is not a correction. This
// matters beyond tidiness: corrected clauses are appended to
// gold_labels as new evaluation targets, and an identical row would
// quietly duplicate an existing label.
if (
  decision === 'correct' &&
  correctedText === (clause.clause_text || '').trim()
) {
  throw new Error(
    'The corrected text is identical to the original extraction. ' +
    'Use "approve" if the extraction was already correct.'
  );
}

// ---------------------------------------------------------------
// Output
// ---------------------------------------------------------------

return [
  {
    json: {
      // Decision data
      decision: decision,
      corrected_text: correctedText.length > 0 ? correctedText : null,
      reviewer_note: reviewerNote.length > 0 ? reviewerNote : null,
      submitted_at: form.submittedAt || null,

      // Context needed by every downstream branch
      review_request_id: Number(email.review_request_id),
      clause_id: Number(email.clause_id),
      document_id: Number(email.document_id),
      token: email.token,

      // Clause detail needed by the 'correct' branch when it writes
      // a new gold_labels row
      clause_type: clause.clause_type,
      filename: clause.filename,
      original_text: clause.clause_text,
      is_absent: clause.is_absent,
    },
  },
];
